import { readFileSync } from 'node:fs'
import path from 'node:path'
import { MAPLIBRE_WORKER_PATH, maplibreWorkerUrl } from '@/lib/maplibre-worker'
import { describe, expect, it } from 'vitest'

describe('maplibreWorkerUrl', () => {
  it('points at the same-origin copy in public/ and carries the version', () => {
    expect(MAPLIBRE_WORKER_PATH).toBe('/maplibre/maplibre-gl-worker.mjs')
    expect(maplibreWorkerUrl('6.16.0')).toBe(
      '/maplibre/maplibre-gl-worker.mjs?v=6.16.0'
    )
  })
})

// public/maplibre/ is generated by scripts/copy-maplibre-worker.mjs (postinstall, dev, build);
// this catches a copy that does not match the installed maplibre-gl.
describe('public MapLibre worker copy', () => {
  it('is identical to the worker shipped in node_modules', () => {
    const root = path.resolve(__dirname, '../..')
    const copy = readFileSync(
      path.join(root, 'public', MAPLIBRE_WORKER_PATH),
      'utf8'
    )
    const installed = readFileSync(
      path.join(root, 'node_modules/maplibre-gl/dist/maplibre-gl-worker.mjs'),
      'utf8'
    )
    expect(copy).toBe(installed)
  })
})
